import{_ as s,l as i,o as a,c as l,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"信号量","description":"","frontmatter":{"title":"信号量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/semaphore.md","filePath":"cs/semaphore.md","lastUpdated":1789023840000}'),h={name:"cs/semaphore.md"};function m(_,e,u,E,P,A){const o=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="信号量" tabindex="-1">信号量 <a class="header-anchor" href="#信号量" aria-label="Permalink to &quot;信号量&quot;">​</a></h1><div class="epigraph"><p>P 操作减少信号量并可能睡眠，V 操作增加并可能唤醒；计数把互斥与资源个数写成同一种对象。</p><footer>—— 据 Dijkstra, Cooperating Sequential Processes, 1965 整理</footer></div><p><a href="/cs/seqlock">上一课</a>给出二元互斥。管道满/空、缓冲区槽位、一次性事件，要的是「还剩几个」以及「没有就睡」。缺口不是再发明一种原子指令，而是把锁字推广成<strong>计数</strong>，并把睡眠/唤醒收进原语——信号量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自旋锁在临界区长或条件暂不成立时浪费 CPU。睡眠互斥锁能等「锁被释放」，但不能表达「等三个槽位空出来」。Dijkstra 的信号量 \\(S\\) 是整数：<code>P(S)</code> 原子地等 \\(S\\gt 0\\) 再减一，<code>V(S)</code> 加一并唤醒。互斥是 \\(S\\) 初值为 \\(1\\) 的特例。缺口是这条原语，不是新的调度器。</p><p>本课不把 Linux <code>down_interruptible</code> 的信号可打断语义写完。</p><p><span class="marginnote">二元信号量像锁，但习惯上不绑定「持有者」：V 可以由另一进程做，这既是灵活也是后课管程要收紧的来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核实现：<code>P</code> 在关中断或持自旋下检查计数，不够则把线程挂到该信号量的等待队列并切换；<code>V</code> 加计数，若有等待者则唤醒。用户库可经系统调用使用。生产者—消费者：空槽与满槽两个信号量，外加互斥保护头尾指针——互斥仍用上一课的锁或第三个信号量。</p>',9)),(a(),n(p,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22P%3A%20%E8%AE%A1%E6%95%B0%E4%B8%8D%E8%B6%B3%E5%88%99%E7%9D%A1%E7%9C%A0%22%5D%20--%3E%20Q%5B%22%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%22%5D%0A%20%20V%5B%22V%3A%20%E5%8A%A0%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20W%5B%22%E5%94%A4%E9%86%92%22%5D%0A%20%20Q%20--%3E%20W%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信号量把<a href="/cs/scheduling-metrics">调度</a>与同步接起来：睡是阻塞状态，V 把人放回就绪。管道的「满写睡」正是对缓冲剩余空间做 P。与纯锁不同，V 可以在中断下半部调用（若实现允许），从而设备完成直接对应「多了一个满槽」。</p><p>计数没有类型系统：对错的信号量做 V 会悄悄破坏不变量。这是下一课管程用语言括号把条件等待收进去的动机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把管程当信号量的宏展开讲完，不引入 barrier、rwlock 的全部变体。也不把 System V 信号量数组的 API 背下来。死锁可以在多信号量上发生，条件在再后一课。</p><p>P 在被信号打断后是否重做，属于接口；课内默认 P 会完成或明确失败，不把 EINTR 表背完。</p><p>忙等信号量极少见，计数等待的意义就是去睡眠。</p><p>后课默认：可以用 P/V 等待资源个数。希望「锁与条件在同一模块里由编译器看管」，下一课管程与条件变量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信号量是带睡眠的计数；互斥是初值为一的特例。</li><li>P/V 把阻塞与唤醒做成原语，对接调度。</li><li>误用 V 难以检查，推动管程。</li><li>出处：Dijkstra, <em>Cooperating Sequential Processes</em>, 1965；Silberschatz et al., <em>OSC</em>。</li></ul>',10))])}const V=s(h,[["render",m]]);export{S as __pageData,V as default};
